#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform float u_time;
uniform vec2 u_mouse;
uniform vec2 u_offset;
uniform float u_zoom;

vec3 rand3(vec3 p) {
	vec3 q = vec3(dot(p, vec3(127.1, 311.7, 74.7)),dot(p, vec3(269.5, 183.3, 246.1)),dot(p, vec3(113.5, 271.9, 124.6)));
	return fract(sin(q) * 43758.5453123);
}

float Checkboard(vec2 uv, float cell_count) {
	vec2 f_uv = fract(uv * cell_count);
	return step(.5, f_uv.x) * step(.5, f_uv.y) + step(-.5, -f_uv.x) * step(-.5, -f_uv.y);
}

float Line(vec2 uv, float cell_count) {
	vec2 f_uv = fract(uv * cell_count);
	return step(.5, f_uv.y);
}

float Tile(vec2 uv, vec4 sides, vec2 id) {

	float threshold = .3;
	float t = step(threshold, sides.x);
	float l = step(threshold, sides.y);
	float r = step(threshold, sides.z);
	float b = step(threshold, sides.w);

	float margin = 0.05;
	float t_tri = step(uv.x, uv.y-margin) * step(1.-uv.y, uv.x-margin);
	float l_tri = step(uv.x, uv.y-margin) * step(uv.x, 1.-uv.y-margin);
	float r_tri = step(uv.y, uv.x-margin) * step(1.-uv.y, uv.x-margin);
	float b_tri = step(uv.y, uv.x-margin) * step(uv.x, 1.-uv.y-margin);

	t_tri *= step(abs(uv.y-1.), 0.15);
	l_tri *= step(abs(uv.x-0.), 0.15);
	r_tri *= step(abs(uv.x-1.), 0.15);
	b_tri *= step(abs(uv.y-0.), 0.15);

	float empty_h = mod(id.x, 2.);
	float empty_v = min(1., mod(id.y, 3.));

	t_tri *= empty_h;
	l_tri *= empty_v;
	r_tri *= empty_v;
	b_tri *= empty_h;

	return t_tri*t + l_tri*l + r_tri*r + b_tri*b;
}

float get_side_seed(vec2 id) {
	return floor( (u_time*.5 + rand3(vec3(id, 0.)).x ) );
}

float WangTiles(vec2 uv, float cell_count) {

	float flow_speed = rand3(vec3( floor(uv.y * cell_count / 3. - .25), 0., 0.)).r;
	uv.x += u_time * (flow_speed*.2 + .1);

	vec2 gv = fract(uv * cell_count);
	vec2 id = floor(uv * cell_count);
	vec2 center_id = floor((uv+vec2(.5)) * cell_count);

	float seed = floor( (u_time + rand3(vec3(id, 0.)).x )*3.);

	vec2 r_id = id + vec2(1.,0.);
	vec2 b_id = id + vec2(0.,-1.);

	vec4 sides = vec4(0.);
	sides.x = rand3(vec3(id, get_side_seed(id))).x;
	sides.y = rand3(vec3(id, get_side_seed(id))).y;
	sides.z = rand3(vec3(r_id, get_side_seed(r_id))).y;
	sides.w = rand3(vec3(b_id, get_side_seed(b_id))).x;

	float tile = Tile(gv, sides, center_id);

	return tile;
}

void main() {
	float c = 0.;
	vec3 col = vec3(0.);
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;
	vec2 mouse = u_mouse / u_resolution.xy;
	mouse = (mouse-.5) * 2.;

	uv += u_offset * 0.001;
	uv *= u_zoom;

	uv -= .5;
	uv *= 1.3;

	uv.y += sin(uv.x*10.) * .03;
	uv.y += uv.x * .3;
	uv.x -= uv.y * .3;

	float pattern = 0.;

	//pattern = Checkboard(uv, 30.);
	//pattern = Line(uv, 30.);

	pattern = WangTiles(uv, 30.);

	c = pattern;

	c = step(.5, c);

  vec3 color1 = vec3(.11, .06, .27);
	vec3 color2 = vec3(.96, .31, .22);

	col = mix(color1, color2, c);

  gl_FragColor = vec4(col,1.0); 
}

